<?php
namespace App\Http\Controllers; use App\Models\{Dispute,Transaction}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class DisputeController extends Controller {public function store(Request $r,Transaction $transaction){abort_unless(in_array($r->user()->id,[$transaction->buyer_id,$transaction->seller_id],true),403);abort_unless(in_array($transaction->status,['paid_held','release_pending'],true),409);$d=$r->validate(['category'=>'required|string|max:80','details'=>'required|string|max:3000','evidence'=>'nullable|file|mimes:jpg,jpeg,png,pdf|max:4096']);DB::transaction(function()use($r,$transaction,$d){$d['complainant_id']=$r->user()->id;if($r->hasFile('evidence'))$d['evidence_path']=$r->file('evidence')->store('disputes/'.$transaction->id,'local');$transaction->disputes()->create($d);$transaction->update(['status'=>'disputed']);});return back()->with('success','Dispute opened. Release is paused while an administrator reviews it.');}}
